"""Offline payload compilation, client replay and origin evidence audit."""
import json
import gc
import math
from pathlib import Path
import re
import sys

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0,'/opt/h3deps')

from schema import compile_cases
from modules.byte_program import Context,MAX
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import audit_channels,TOKEN

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z',re.ASCII)


def exact(obj,keys):
    if type(obj) is not dict or set(obj)!=set(keys):
        raise ValueError('object keys')


def integer(value,minimum=0,maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('integer')
    return value


def sequence(value,maximum):
    if type(value) is not list or len(value)>maximum:
        raise ValueError('array')
    return value


def text(value,maximum=65536):
    if type(value) is not str or len(value)>maximum:
        raise ValueError('string')
    value.encode('utf8')
    return value


def pairs(items):
    out = {}
    for key,value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON')
    return result


def compile_document(document):
    exact(document,['seed','definitions','timeout_ms','cases','events','channels'])
    seed = text(document['seed'],64)
    if any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-' for c in seed):
        raise ValueError('seed')
    definitions = sequence(document['definitions'],8192)
    for row in definitions:
        sequence(row,2)
        if len(row)!=2:
            raise ValueError('definition pair')
        text(row[0],32)
        text(row[1],8192)
    context = Context(definitions,seed)
    timeout = integer(document['timeout_ms'],1,10**9)
    cases = sequence(document['cases'],2000)
    names = set()
    budget = 0
    fields_count = 0
    for case in cases:
        exact(case,['name','frames','expect'])
        name = text(case['name'],32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'],50000)
        budget += len(frames)
        pause_total = 0
        for frame in frames:
            if type(frame) is not dict or type(frame.get('Type')) is not str:
                raise ValueError('frame')
            if frame['Type']=='sleep':
                pause_total += integer(frame.get('Time_to_Stop'))
            if frame['Type']=='headers':
                if frame.get('headers_kv') is not None:
                    value = frame['headers_kv']
                    if type(value) is not dict:
                        raise ValueError('header mapping')
                    fields_count += len(value)
                elif frame.get('data_to_transfered') is not None:
                    value = sequence(frame['data_to_transfered'],128)
                    fields_count += len(value)
        if pause_total+timeout > MAX:
            raise ValueError('time overflow')
        exp = case['expect']
        exact(exp,['method','target','host'])
        for k in exp:
            value = text(exp[k],8192).encode('ascii')
            if not value or not all(33 <= c <= 126 for c in value):
                raise ValueError('expected identity')
        if TOKEN.fullmatch(exp['method'].encode('ascii')) is None:
            raise ValueError('expected method')
    payload = compile_cases(cases,context)
    payload_dict = payload.model_dump()
    actual_test_cases = {}
    for case_name,frames in payload_dict['test_cases'].items():
        clean_frames = []
        for frame in frames:
            if 'headers_kv' in frame:
                del frame['headers_kv']
            clean_frames.append(frame)
        actual_test_cases[case_name] = clean_frames
    records = sequence(document['events'],50000)
    budget += len(records)
    events = []
    for index,record in enumerate(records):
        if type(record) is not dict:
            raise ValueError('event')
        kind = record.get('kind')
        keys = ['at','kind'] if kind=='close' else ['at','kind','stream','end',('fields' if kind=='headers' else 'data')]
        exact(record,keys)
        integer(record['at'])
        if kind not in ('close','headers','data'):
            raise ValueError('event kind')
        row = record.copy()
        if kind!='close':
            integer(row['stream'],0,(1 << 32)-1)
            if type(row['end']) is not bool:
                raise ValueError('event end')
        if kind=='headers':
            raw_fields = sequence(row['fields'],128)
            fields_count += len(raw_fields)
            fields = []
            for j,pair in enumerate(raw_fields):
                sequence(pair,2)
                if len(pair)!=2:
                    raise ValueError('event field pair')
                fields.append((context.template(text(pair[0]),f'event/{index}/h/{j}/n'),
                               context.template(text(pair[1]),f'event/{index}/h/{j}/v')))
            row['fields'] = fields
        elif kind=='data':
            row['data'] = context.template(text(row['data']),f'event/{index}/data')
        events.append(row)
    channels = sequence(document['channels'],256)
    channel_names = set()
    compiled_channels = []
    for index,channel in enumerate(channels):
        exact(channel,['name','parts'])
        name = text(channel['name'],32)
        if not NAME.fullmatch(name) or name in channel_names:
            raise ValueError('channel name')
        channel_names.add(name)
        parts = sequence(channel['parts'],50000)
        budget += len(parts)
        out_parts = []
        for j,part in enumerate(parts):
            exact(part,['case','data'])
            owner = part['case']
            if owner is not None and (type(owner) is not str or owner not in names):
                raise ValueError('owner label')
            out_parts.append({'case':owner,'data':context.template(text(part['data']),f'channel/{index}/part/{j}/data')})
        compiled_channels.append({'name':name,'parts':out_parts})
    if budget>50000 or fields_count>32768:
        raise ValueError('combined budget')
    return cases,actual_test_cases,events,compiled_channels,timeout


def run(document):
    cases,actual_test_cases,events,channels,timeout = compile_document(document)
    fuzzer = FuzzExecutor()
    sent = fuzzer.send_payload(actual_test_cases,events,timeout)
    origin = audit_channels(channels,cases,sent)
    return {'cases':sent,'channels':origin}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(8*1024**2+1)
        if len(raw)>8*1024**2:
            raise ValueError('input bytes')
        document = json.loads(raw.decode('utf8'),object_pairs_hook=pairs,
                              parse_constant=bad_constant,parse_float=finite_float)
        result = run(document)
    except (ValueError,TypeError,KeyError,IndexError,UnicodeError,RecursionError):
        result = {'error':'input'}
    encoded=json.dumps(result,ensure_ascii=True,separators=(',',':'),allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded+b'\n')


if __name__=='__main__':main()

import ast
import operator
from pydantic import BaseModel, Field, model_validator, field_validator
from typing import List, Union, Literal, Dict, Optional, Any
import logging
import random
import secrets
import string

logger = logging.getLogger("PayloadEvaluator")

def safe_eval_payload(expr: str, max_length: int = 1024 * 1024 * 5):
    operators = {
        ast.Add: operator.add,
        ast.Mult: operator.mul
    }

    def _eval(node):
        if isinstance(node, ast.Constant):
            return node.value

        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)

            op_type = type(node.op)
            if op_type in operators:
                if op_type == ast.Mult:

                    is_left_str = isinstance(left, str)
                    is_right_str = isinstance(right, str)
                    if is_left_str or is_right_str:

                        target_str = left if is_left_str else right
                        multiplier = right if is_left_str else left

                        if isinstance(target_str, str) and isinstance(multiplier, int):
                            if len(target_str) * multiplier > max_length:
                                raise ValueError(f"Payload result exceeds limit of {max_length} bytes")

                try:
                    return operators[op_type](left, right)
                except Exception as e:
                    raise ValueError(f"Calculation error: {e}")
            else:
                raise ValueError(f"Unsupported operator: {op_type}")

        else:
            raise ValueError(f"Unsupported syntax type: {type(node).__name__}")

    try:
        tree = ast.parse(expr, mode='eval')
        return _eval(tree.body)
    except Exception as e:
        logger.error(f"Failed to evaluate expression '{expr}': {e}")
        return expr


def expand_complex_expression(value: str) -> str:
    if not isinstance(value, str):
        return value

    if "{{" in value and "}}" in value:
        import re
        pattern = r'\{\{(.*?)\}\}'

        def replace_func(match):
            code_snippet = match.group(1).strip()
            try:
                result = safe_eval_payload(code_snippet)
                return str(result)
            except Exception as e:
                return match.group(0)
        return re.sub(pattern, replace_func, value)

    while "<<random_string>>" in value:
        length = random.randint(5, 100)
        chars = string.ascii_letters + string.digits
        rand_str = ''.join(secrets.choice(chars) for _ in range(length))
        value = value.replace("<<random_string>>", rand_str, 1)

    return value


class H3HeaderFrame(BaseModel):
    Type: Literal["headers"] = Field("headers", description="Fixed value, 'headers'")
    headers_kv: Optional[Dict[str, str]] = Field(
        None,
        description="[Recommended] Pass headers using a dictionary format, for example: {':method': 'GET', ':path': '/'}"
    )
    data_to_transfered: Optional[List[List[str]]] = Field(
        None,
        description="Internal field, typically automatically generated by headers_kv. If specified directly, it must be a two-dimensional array [[k,v], ...]"
    )

    End_Stream: bool = Field(False, description="Whether to end the stream after this frame.")

    @model_validator(mode='after')
    def process_headers(self):
        if self.headers_kv:
            self.data_to_transfered = []
            for k, v in self.headers_kv.items():
                expanded_v = expand_complex_expression(str(v))
                self.data_to_transfered.append([k, expanded_v])

        elif self.data_to_transfered:
            new_data = []
            for item in self.data_to_transfered:
                if len(item) == 2:
                    k, v = item
                    expanded_v = expand_complex_expression(str(v))
                    new_data.append([k, expanded_v])
                else:
                    new_data.append(item)
            self.data_to_transfered = new_data

        if self.data_to_transfered is None:
            self.data_to_transfered = []
        return self


class H3DataFrame(BaseModel):
    Type: Literal["data", "datagram"] = Field("data", description="usually 'data'")
    data_to_transfered: str = Field(
        ...,
        description="Raw string content of the payload. Note: Must be a string."
    )

    End_Stream: bool = Field(True, description="Whether to end the stream after this frame.")

    @field_validator('data_to_transfered', mode='before')
    def process_data(cls, v):
        return expand_complex_expression(str(v))


class H3SleepFrame(BaseModel):
    Type: Literal["sleep"] = "sleep"
    Time_to_Stop: int = Field(..., description="Pause duration (milliseconds)")

class FuzzingPayload(BaseModel):
    test_cases: Dict[str, List[Union[H3HeaderFrame, H3DataFrame, H3SleepFrame]]] = Field(
        ...,
        description="A collection of test cases. The key is the test case name (User-Agent), and the value is the list of frames."
    )


def compile_cases(cases, context):
    classes = {'headers': H3HeaderFrame, 'data': H3DataFrame,
               'datagram': H3DataFrame, 'sleep': H3SleepFrame}
    data = {}
    for case in cases:
        data[case['name']] = [classes[frame['Type']].model_validate(frame)
                              for frame in case['frames']]
    return FuzzingPayload.model_construct(test_cases=data)

"""Byte-sequence API for the compressed payload extension.

Only literal input plumbing is supplied. Complete the operations and Context.
You may replace this representation or reorganize the project.
"""
MAX = (1 << 63) - 1


def literal(data):
    return data


def size(node):
    return len(node) if node is not None else 0


def concat(a, b):
    raise NotImplementedError('compressed sequence concatenation')


def repeat(node, count):
    raise NotImplementedError('compressed sequence repetition')


def cut(node, start, end):
    raise NotImplementedError('compressed byte slices')


def materialize(node, limit=65536):
    if size(node) > limit:
        raise ValueError('bounded materialization')
    return node or b''


def fingerprint(node):
    raise NotImplementedError('exact byte fingerprint')


def next_lf(node, start=0):
    raise NotImplementedError('capture line access')


class Context:
    def __init__(self, definitions, seed):
        self.seed = seed
        self.definitions = definitions
        if definitions:
            raise NotImplementedError('shared byte definitions')

    def expression(self, text):
        raise NotImplementedError('typed compressed expressions')

    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError('template type')
        return literal(value.encode('utf8'))

"""Single-thread coroutine driver for an offline event tape; no sockets."""
import heapq


class Future:
    def __init__(self):
        self.value = None
        self.error = None
        self.finished = False
        self.listeners = []

    def done(self):
        return self.finished

    def set_result(self, value):
        if self.finished:
            return
        self.finished = True
        self.value = value
        for callback in self.listeners:
            callback(self)
        self.listeners.clear()

    def set_exception(self, error):
        if self.finished:
            return
        self.error = error
        self.set_result(None)

    def __await__(self):
        if not self.finished:
            yield self
        if self.error is not None:
            raise self.error
        return self.value


class Task(Future):
    def __init__(self, clock, coroutine):
        super().__init__()
        self.clock = clock
        self.coroutine = coroutine

    def step(self, previous=None):
        if self.finished:
            return
        try:
            if previous is not None and previous.error is not None:
                wait = self.coroutine.throw(previous.error)
            else:
                wait = self.coroutine.send(None if previous is None else previous.value)
        except StopIteration as stop:
            self.set_result(stop.value)
            return
        except Exception as exc:
            self.set_exception(exc)
            return
        if not isinstance(wait,Future):
            self.set_exception(TypeError('unsupported awaitable'))
            return
        wait.listeners.append(self.step)


class Clock:
    def __init__(self):
        self.now = 0
        self.events = []
        self.sequence = 0

    def create_future(self):
        return Future()

    def schedule(self, time, kind, order, callback):
        if not self.now <= time <= (1 << 63)-1:
            raise ValueError('clock range')
        self.sequence += 1
        heapq.heappush(self.events,(time,kind,order,self.sequence,callback))

    def sleep(self, duration, order):
        f = Future()
        self.schedule(self.now+duration,1,order,lambda:f.set_result(None))
        return f

    def run(self, coroutines, records, dispatch):
        tasks = [Task(self,c) for c in coroutines]
        for index, task in enumerate(tasks):
            self.schedule(0,-1,index,task.step)
        for index, record in enumerate(records):
            self.schedule(record['at'],0,index,lambda r=record:dispatch(r))
        while self.events:
            time,_,_,_,callback = heapq.heappop(self.events)
            self.now = time
            callback()
        if any(not task.done() for task in tasks):
            raise RuntimeError('unfinished offline task')
        for task in tasks:
            if task.error is not None:
                raise task.error
        return [task.value for task in tasks]

"""Decoded event records consumed by HttpClient in offline mode."""
from dataclasses import dataclass


class SendError(Exception):
    pass


@dataclass
class HeadersReceived:
    stream_id: int
    headers: list
    stream_ended: bool


@dataclass
class DataReceived:
    stream_id: int
    data: object
    stream_ended: bool


@dataclass
class ConnectionTerminated:
    error_code: int = 0
    reason_phrase: str = 'capture close'

"""FuzzExecutor frame conversion and execution against an injected transport."""
from HTTP3_Just_Send import HttpClient
from modules.clock import Clock
from modules.events import HeadersReceived, DataReceived, ConnectionTerminated, SendError
from modules.byte_program import literal, concat, fingerprint, size


def encoded_action(at, stream, kind, data, end=False):
    head = literal(at.to_bytes(8,'big')+stream.to_bytes(4,'big')+kind.encode('ascii'))
    if kind in ('H','h'):
        head = concat(head,literal(len(data).to_bytes(8,'big')))
        for name,value in data:
            head = concat(head,literal(size(name).to_bytes(8,'big')))
            head = concat(head,name)
            head = concat(head,literal(size(value).to_bytes(8,'big')))
            head = concat(head,value)
    else:
        head = concat(head,literal(size(data).to_bytes(8,'big')))
        head = concat(head,data)
    return concat(head,literal(bytes([bool(end)])))


class OfflineTransport:
    def __init__(self, clock, count):
        self.clock = clock
        self.next_stream = 0
        self.ended = set()
        self.sent = [None]*count
        self.frames = [0]*count
        self.request_frames = [0]*count
        self.payload_bytes = [0]*count
        self.client = None

    def get_next_available_stream_id(self):
        stream = self.next_stream
        self.next_stream += 4
        return stream

    def record(self, stream_id, kind, data, end_stream=False):
        if stream_id in self.ended:
            raise SendError('frame after request end')
        index = stream_id//4
        action = encoded_action(self.clock.now,stream_id,kind,data,end_stream)
        self.sent[index] = concat(self.sent[index],action)
        self.frames[index] += 1
        if kind in ('H','D'):
            self.request_frames[index] += 1
        self.payload_bytes[index] += sum(size(n)+size(v) for n,v in data) if kind=='H' else size(data)
        if end_stream:
            self.ended.add(stream_id)

    def send_headers(self, stream_id, headers, end_stream):
        self.record(stream_id,'H',headers,end_stream)

    def send_data(self, stream_id, data, end_stream):
        self.record(stream_id,'D',data,end_stream)

    def send_datagram(self, stream_id, data):
        self.record(stream_id,'G',data)

    def dispatch(self, record):
        if record['kind']=='close':
            self.client.quic_event_received(ConnectionTerminated())
        elif record['kind']=='headers':
            self.client.quic_event_received(HeadersReceived(record['stream'],record['fields'],record['end']))
        else:
            self.client.quic_event_received(DataReceived(record['stream'],record['data'],record['end']))


class FuzzExecutor:
    def __init__(self, target_ip=None, target_port=None, domain=None):
        self.target_ip = target_ip
        self.target_port = target_port
        self.domain = domain

    def _convert_single_case_frames(self, frames: List[Dict]) -> List[Dict]:
        converted_frames = []

        for item in frames:
            new_item = {}
            new_item["Type"] = item.get("Type")
            new_item["End_Stream"] = item.get("End_Stream", False)

            if "Time_to_Stop" in item:
                new_item["Time_to_Stop"] = item["Time_to_Stop"]

            raw_data = item.get("data_to_transfered")

            if new_item["Type"] == "headers":
                headers = []
                if isinstance(raw_data, list):
                    for pair in raw_data:
                        if len(pair) >= 2:
                            k = str(pair[0]).encode('utf-8')
                            v = str(pair[1]).encode('utf-8')
                            headers.append((k, v))
                new_item["data_to_transfered"] = headers

            elif new_item["Type"] in ["data", "datagram"]:
                if raw_data is not None:
                    new_item["data_to_transfered"] = str(raw_data).encode('utf-8')
                else:
                    new_item["data_to_transfered"] = b""

            converted_frames.append(new_item)

        return converted_frames

    def send_payload(self, llm_output, records, timeout_ms):
        clock = Clock()
        transport = OfflineTransport(clock,len(llm_output))
        client = HttpClient(clock,transport,timeout_ms)
        transport.client = client
        coroutines = []
        for index,(case_name,frames) in enumerate(llm_output.items()):
            payload = self._convert_single_case_frames(frames)
            coroutines.append(client.request(payload,index))
        results = clock.run(coroutines,records,transport.dispatch)
        out = []
        for index,result in enumerate(results):
            received = None
            body = None
            for at,event in result['events']:
                if isinstance(event,HeadersReceived):
                    encoded = encoded_action(at,result['stream'],'h',event.headers,event.stream_ended)
                else:
                    encoded = encoded_action(at,result['stream'],'d',event.data,event.stream_ended)
                    body = concat(body,event.data)
                received = concat(received,encoded)
            out.append({'name':list(llm_output)[index],'stream':result['stream'],
                'state':result['state'],'at':result['at'],'frames':transport.frames[index],
                'request_frames':transport.request_frames[index],
                'payload_bytes':transport.payload_bytes[index],
                'sent':fingerprint(transport.sent[index]),'received':fingerprint(received),
                'response_frames':len(result['events']),'response_body':fingerprint(body),
                'origin_count':0,'flags':[]})
        return out

"""HttpClient request/event core with an injected offline transport and clock."""
from collections import deque
from modules.events import HeadersReceived, DataReceived, ConnectionTerminated, SendError


class HttpClient:
    def __init__(self, clock, backend, timeout_ms):
        self._loop = clock
        self._http = backend
        self._quic = backend
        self._timeout_ms = timeout_ms
        self._request_events = {}
        self._request_waiter = {}
        self._request_timeout_handlers = {}
        self._pauses = {}
        self._sending = {}
        self._response_ended = set()
        self._close_info = None

    def _log(self, msg):
        pass

    async def request(self, Case, case_index):
        stream_id = self._quic.get_next_available_stream_id()
        self._request_events[stream_id] = deque()
        self._sending[stream_id] = True
        state = 'ok'
        try:
            for item in Case:
                if self._close_info is not None:
                    raise ConnectionError(self._close_info)
                if item['Type'] == 'headers':
                    self._http.send_headers(stream_id=stream_id,
                        headers=item['data_to_transfered'],end_stream=item['End_Stream'])
                elif item['Type'] == 'data':
                    self._http.send_data(stream_id=stream_id,
                        data=item['data_to_transfered'],end_stream=item['End_Stream'])
                elif item['Type'] == 'datagram':
                    self._http.send_datagram(stream_id=stream_id,data=item['data_to_transfered'])
                elif item['Type'] == 'sleep':
                    pause = self._loop.sleep(item['Time_to_Stop'],case_index)
                    self._pauses[stream_id] = pause
                    await pause
                    self._pauses.pop(stream_id,None)
                    continue
                self.transmit()
            self._sending[stream_id] = False
            waiter = self._loop.create_future()
            self._request_waiter[stream_id] = waiter
            deadline = self._loop.now + self._timeout_ms
            self._request_timeout_handlers[stream_id] = deadline
            self._loop.schedule(deadline,2,case_index,
                lambda sid=stream_id:self._handle_request_timeout(sid))
            await waiter
        except ConnectionError:
            state = 'closed'
        except TimeoutError:
            state = 'timeout'
        except SendError:
            state = 'send_error'
        events = list(self._request_events.pop(stream_id,()))
        self._request_waiter.pop(stream_id,None)
        self._request_timeout_handlers.pop(stream_id,None)
        self._pauses.pop(stream_id,None)
        self._sending.pop(stream_id,None)
        return {'state':state,'at':self._loop.now,'events':events,'stream':stream_id}

    def transmit(self):
        return None

    def _handle_request_timeout(self, stream_id):
        if stream_id in self._request_waiter and not self._request_waiter[stream_id].done():
            self._cancel_request(stream_id,'Time Out')

    def _cancel_request(self, stream_id, reason):
        if stream_id in self._request_waiter:
            waiter = self._request_waiter[stream_id]
            if not waiter.done():
                waiter.set_exception(TimeoutError(reason))

    def http_event_received(self, event):
        stream_id = event.stream_id
        if stream_id in self._request_events and stream_id not in self._response_ended:
            self._request_events[stream_id].append((self._loop.now,event))
            if event.stream_ended:
                self._response_ended.add(stream_id)
                if not self._sending[stream_id]:
                    waiter = self._request_waiter[stream_id]
                    if not waiter.done():
                        waiter.set_result(None)

    def quic_event_received(self, event):
        if isinstance(event,ConnectionTerminated):
            self._close_info = event.reason_phrase
            for stream_id, waiter in list(self._request_waiter.items()):
                if not waiter.done():
                    waiter.set_exception(ConnectionError(self._close_info))
            for stream_id, pause in list(self._pauses.items()):
                if not pause.done():
                    pause.set_exception(ConnectionError(self._close_info))
        else:
            self.http_event_received(event)

    def connection_lost(self, exc=None):
        self.quic_event_received(ConnectionTerminated(reason_phrase='Connection lost'))

"""Public sanity checker: bounded child CLI, no private inputs and no score."""
import json
import math
import os
from pathlib import Path
import selectors
import signal
import stat
import subprocess
import sys
import time

HERE = Path(__file__).resolve().parent


class CandidateFailure(Exception):
    pass


class InfrastructureError(Exception):
    pass


def unique_object(items):
    out = {}
    for k, v in items:
        if k in out:
            raise ValueError('duplicate output key')
        out[k] = v
    return out


def invalid_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError('nonfinite JSON number')
    return value


def parse_output(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object,
                      parse_constant=invalid_constant, parse_float=finite_float)


def canonical(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=True, separators=(',', ':'), allow_nan=False)


def storage_over_budget(scratch):
    total = entries = 0
    stack = [scratch]
    while stack:
        p = stack.pop()
        try:
            s = p.lstat()
            entries += 1
            if stat.S_ISREG(s.st_mode):
                total += max(s.st_size, s.st_blocks*512)
            elif stat.S_ISDIR(s.st_mode):
                with os.scandir(p) as children:
                    stack.extend(Path(e.path) for e in children)
        except FileNotFoundError:
            continue
        if total > 1024**3 or entries > 50000:
            return True
    return False


def invoke(candidate, raw):
    if os.geteuid() == 0:
        raise InfrastructureError('refusing root candidate execution; use the image default user')
    scratch = Path('/workspace/tmp')
    # The public image owns this dedicated directory; the private worker also
    # clears it before invocation. Only remove scratch entries, never submissions.
    import shutil
    for entry in scratch.iterdir():
        if entry.is_dir() and not entry.is_symlink():
            shutil.rmtree(entry)
        else:
            entry.unlink()
    env = {'PATH':'/usr/local/bin:/usr/bin:/bin', 'LANG':'C', 'LC_ALL':'C',
           'HOME':'/workspace', 'TMPDIR':str(scratch), 'PYTHONHASHSEED':'0',
           'PYTHONUNBUFFERED':'1', 'PYTHONDONTWRITEBYTECODE':'1',
           'OPENBLAS_NUM_THREADS':'1', 'OMP_NUM_THREADS':'1', 'MKL_NUM_THREADS':'1'}
    p = None
    sel = selectors.DefaultSelector()
    streams = []
    buffers = [bytearray(), bytearray()]
    limits = [16*1024**2, 1024**2]
    offset = 0
    deadline = time.monotonic()+60
    next_storage = 0
    try:
        previous = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGTERM, signal.SIGINT})
        try:
            p = subprocess.Popen([sys.executable, '-I', '-B', str(HERE/'runner.py'), str(candidate)],
                                 stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                 cwd='/workspace', env=env, close_fds=True)
            streams = [p.stdin, p.stdout, p.stderr]
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, previous)
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if raw:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        while sel.get_map():
            now = time.monotonic()
            if now >= deadline:
                raise CandidateFailure('wall timeout')
            if now >= next_storage:
                if storage_over_budget(scratch):
                    raise InfrastructureError('scratch emergency brake; no score')
                next_storage = now+.25
            for key, _ in sel.select(min(.1, deadline-now)):
                stream, kind = key.fileobj, key.data
                if kind == -1:
                    try:
                        n = os.write(stream.fileno(), memoryview(raw)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(stream)
                        stream.close()
                        continue
                    offset += n
                    if offset == len(raw):
                        sel.unregister(stream)
                        stream.close()
                else:
                    try:
                        block = os.read(stream.fileno(), min(65536,limits[kind]-len(buffers[kind])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream)
                        stream.close()
                    elif len(buffers[kind])+len(block) > limits[kind]:
                        raise CandidateFailure(('stdout','stderr')[kind]+' limit')
                    else:
                        buffers[kind].extend(block)
        try:
            code = p.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired:
            raise CandidateFailure('wall timeout') from None
        if code:
            raise CandidateFailure('nonzero exit status')
        try:
            return parse_output(bytes(buffers[0]))
        except (UnicodeError, ValueError, RecursionError):
            raise CandidateFailure('missing or malformed JSON output') from None
    finally:
        # Candidate code starts only after no-fork seccomp is installed.
        if p is not None:
            if p.poll() is None:
                p.kill()
            p.wait(timeout=5)
        sel.close()
        for stream in streams:
            stream.close()


def interrupted(signum, frame):
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    raise KeyboardInterrupt()


def main():
    for sig in (signal.SIGTERM, signal.SIGINT):
        signal.signal(sig, interrupted)
    if len(sys.argv) != 2:
        raise SystemExit('usage: python3 check.py /workspace/project')
    candidate = Path(sys.argv[1]).absolute() / 'main.py'
    s = candidate.lstat()
    if not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_size > 8*1024*1024:
        raise SystemExit('submission file must be regular, one link, at most 8 MiB')
    fixtures = json.loads((HERE/'examples.json').read_text())
    try:
        for row in fixtures:
            value = invoke(candidate, row['stdin'].encode('utf-8'))
            try:
                actual = canonical(value)
            except (ValueError, RecursionError, OverflowError):
                raise CandidateFailure('malformed JSON output') from None
            if actual != canonical(row['expected']):
                raise CandidateFailure(row['name']+': output differs from public expectation')
    except KeyboardInterrupt:
        print('INTERRUPTED: no result', file=sys.stderr)
        return 130
    except CandidateFailure as e:
        print('FAIL: '+str(e), file=sys.stderr)
        return 1
    except InfrastructureError as e:
        print('INFRASTRUCTURE ERROR: '+str(e), file=sys.stderr)
        return 2
    print('PASS: '+str(len(fixtures))+' public CLI fixtures (no score)')
    return 0


if __name__ == '__main__':
    sys.exit(main())

