MASK=(1<<64)-1
def fp(b):
 h=0
 for x in b:h=(h*257+x+1)&MASK
 return {'n':len(b),'h':f'{h:016x}'}
def H(t,s,kind,pairs,end):
 b=t.to_bytes(8,'big')+s.to_bytes(4,'big')+kind+len(pairs).to_bytes(8,'big')
 for n,v in pairs:b+=len(n).to_bytes(8,'big')+n+len(v).to_bytes(8,'big')+v
 return b+bytes([end])
def D(t,s,kind,data,end):
 return t.to_bytes(8,'big')+s.to_bytes(4,'big')+kind+len(data).to_bytes(8,'big')+data+bytes([end])
